mapper.select:
SELECT ds.created AS saleTime, ds.patientName AS patientName, ds.age AS ageStr, p.gender AS gender, ds.operatorPerson AS doctor, di.drugName AS drugName, di.specification AS specification, di.manufacturer AS manufacturer, di.unitPrice AS unitPrice, di.quantity AS quantity, di.unit AS unit, di.amount AS totalAmount, ds.statusRemark AS chargeStatus FROM bq_drug_sales ds LEFT JOIN bq_drug_sales_item di ON di.salesId = ds.id AND di.deleted = 0 LEFT JOIN bq_patient p ON p.name = ds.patientName AND p.deleted = 0 WHERE ds.deleted = 0
AND di.drugName LIKE CONCAT('%', #{drugName}, '%')
AND ds.operatorPerson = #{doctor}
AND ds.created >= #{startTime}
AND ds.created <= #{endTime}
ORDER BY ds.created DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM bq_drug_sales ds
LEFT JOIN bq_drug_sales_item di ON di.salesId = ds.id AND di.deleted = 0
WHERE ds.deleted = 0

    AND di.drugName LIKE CONCAT('%', #{drugName}, '%')


    AND ds.operatorPerson = #{doctor}


    AND ds.created >= #{startTime}


    AND ds.created <= #{endTime}

SELECT di.drugName AS drugName, di.specification AS specification, di.unit AS unit, di.manufacturer AS manufacturer, COUNT(*) AS saleTimes, SUM(CAST(di.quantity AS DECIMAL(15,2))) AS totalQuantity, ROUND(COALESCE(SUM(CAST(di.amount AS DECIMAL(15,2))), 0), 2) AS totalAmount, ROUND(COALESCE(AVG(CAST(di.unitPrice AS DECIMAL(15,4))), 0), 4) AS avgPrice FROM bq_drug_sales ds LEFT JOIN bq_drug_sales_item di ON di.salesId = ds.id AND di.deleted = 0 WHERE ds.deleted = 0
AND di.drugName LIKE CONCAT('%', #{drugName}, '%')
AND ds.created >= #{startTime}
AND ds.created <= #{endTime}
GROUP BY di.drugName, di.specification, di.unit, di.manufacturer ORDER BY totalAmount DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM (
    SELECT 1
    FROM bq_drug_sales ds
    LEFT JOIN bq_drug_sales_item di ON di.salesId = ds.id AND di.deleted = 0
    WHERE ds.deleted = 0

        AND di.drugName LIKE CONCAT('%', #{drugName}, '%')


        AND ds.created >= #{startTime}


        AND ds.created <= #{endTime}

    GROUP BY di.drugName, di.specification, di.unit, di.manufacturer
) t

SELECT COUNT(DISTINCT di.drugName) AS drugTypeCount, ROUND(COALESCE(SUM(CAST(di.quantity AS DECIMAL(15,2))), 0), 2) AS totalQuantity, ROUND(COALESCE(SUM(CAST(di.amount AS DECIMAL(15,2))), 0), 2) AS totalAmount FROM bq_drug_sales ds LEFT JOIN bq_drug_sales_item di ON di.salesId = ds.id AND di.deleted = 0 WHERE ds.deleted = 0
AND di.drugName LIKE CONCAT('%', #{drugName}, '%')
AND ds.created >= #{startTime}
AND ds.created <= #{endTime}
